import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

/**
 * 受试者替补业务：
 * 仅对已退组且从未揭盲的参与者可替补；同一事务内把原分配行原地转移给替补参与者
 * （不新建分配序号、不改变区组席位与处理代码配额），原参与者转为 REPLACED 终态。
 * 替补记录不可变且不包含处理代码；处理代码不返回给操作人。
 * 区组可用名额 = 总席位 - 未退组且未替补的参与者数，退组释放的名额恰被替补填回，账目守恒。
 */
@Service
public class ReplacementService {

    private final ExperimentRepository experimentRepository;
    private final AllocationRepository allocationRepository;
    private final ReplacementRepository replacementRepository;
    private final UnblindRequestRepository unblindRequestRepository;
    private final BlindCodeGenerator blindCodeGenerator;
    private final Clock clock;

    public ReplacementService(ExperimentRepository experimentRepository,
                              AllocationRepository allocationRepository,
                              ReplacementRepository replacementRepository,
                              UnblindRequestRepository unblindRequestRepository,
                              BlindCodeGenerator blindCodeGenerator,
                              Clock clock) {
        this.experimentRepository = experimentRepository;
        this.allocationRepository = allocationRepository;
        this.replacementRepository = replacementRepository;
        this.unblindRequestRepository = unblindRequestRepository;
        this.blindCodeGenerator = blindCodeGenerator;
        this.clock = clock;
    }

    /**
     * 替补登记：实验行锁串行化同实验并发，分配行锁与揭盲批准互斥，
     * 按事务提交顺序裁决（替补先提交则后续对原参与者揭盲 409，反之替补 409）。
     */
    @Transactional
    public ReplacementView replace(String experimentId, String originalParticipantId,
                                   String replaceKey, String newParticipantId, String actorId) {
        if (replaceKey == null || replaceKey.isBlank()) {
            throw ApiException.badRequest("replaceKey 不能为空");
        }
        if (newParticipantId == null || newParticipantId.isBlank()) {
            throw ApiException.badRequest("newParticipantId 不能为空");
        }
        ExperimentRow experiment = experimentRepository.lockById(experimentId);
        if (experiment == null) {
            throw ApiException.notFound("实验不存在: " + experimentId);
        }
        AllocationRow allocation =
                allocationRepository.lockByExperimentAndParticipant(experimentId, originalParticipantId);
        if (allocation == null) {
            if (replacementRepository.findByOriginal(experimentId, originalParticipantId) != null) {
                throw ApiException.conflict("参与者已被替补，处于 REPLACED 终态");
            }
            throw ApiException.notFound("参与者尚未在该实验登记");
        }
        if (!"WITHDRAWN".equals(allocation.status())) {
            // 未退组（在组）不可替补。
            throw ApiException.conflict("仅已退组且未揭盲的参与者可替补");
        }
        if (unblindRequestRepository.existsApprovedByAllocation(allocation.id())) {
            throw ApiException.conflict("参与者已揭盲，不可替补");
        }
        if (allocationRepository.findByExperimentAndParticipant(experimentId, newParticipantId) != null
                || replacementRepository.findByOriginal(experimentId, newParticipantId) != null
                || replacementRepository.findByNew(experimentId, newParticipantId) != null) {
            // 新参与者已存在于区组或拥有历史分配（含曾被替补、曾作为替补者）。
            throw ApiException.conflict("新参与者已存在或拥有历史分配: " + newParticipantId);
        }
        long now = clock.nowMillis();
        transferWithUniqueBlindCode(allocation, newParticipantId, actorId, now);
        ReplacementRow record = new ReplacementRow(0L, replaceKey, experimentId,
                allocation.blockNo(), allocation.id(), originalParticipantId,
                newParticipantId, actorId, now);
        try {
            replacementRepository.insert(record);
        } catch (DuplicateKeyException e) {
            // replaceKey 重复或并发替补同一参与者，由唯一约束兜底。
            throw ApiException.conflict("replaceKey 已被使用或参与者替补冲突");
        }
        return toView(record);
    }

    /**
     * 原地转移分配行并更换盲码；盲码全局唯一冲突时重试，状态守卫失败按并发冲突处理。
     */
    private void transferWithUniqueBlindCode(AllocationRow allocation, String newParticipantId,
                                             String actorId, long now) {
        for (int attempt = 0; attempt < 5; attempt++) {
            String blindCode = blindCodeGenerator.nextCode();
            try {
                int updated = allocationRepository.transferToReplacement(
                        allocation.id(), newParticipantId, blindCode, actorId, now);
                if (updated == 0) {
                    throw ApiException.conflict("参与者状态已变化，替补冲突，请重试");
                }
                return;
            } catch (DuplicateKeyException e) {
                if (allocationRepository.isDuplicateBlindCode(e)) {
                    continue;
                }
                // 新参与者占位或席位冲突：唯一约束兜底。
                throw ApiException.conflict("新参与者已存在或席位冲突，请重试");
            }
        }
        throw ApiException.conflict("盲码生成冲突，请重试");
    }

    /**
     * 区组替补历史（不含处理代码与席位号）。
     */
    public List<ReplacementView> listBlockReplacements(String experimentId, int blockNo) {
        mustFindBlock(experimentId, blockNo);
        return replacementRepository.listByBlock(experimentId, blockNo).stream()
                .map(this::toView)
                .toList();
    }

    /**
     * 区组名额统计（不含处理代码）：可用名额 = 总席位 - 未退组且未替补的参与者数。
     */
    public BlockQuotaView getBlockQuota(String experimentId, int blockNo) {
        mustFindBlock(experimentId, blockNo);
        long active = allocationRepository.countActiveByBlock(experimentId, blockNo);
        int total = ExperimentService.SEATS_PER_BLOCK;
        return new BlockQuotaView(experimentId, blockNo, total, active, total - active);
    }

    private ExperimentRow mustFindBlock(String experimentId, int blockNo) {
        ExperimentRow experiment = experimentRepository.findById(experimentId);
        if (experiment == null) {
            throw ApiException.notFound("实验不存在: " + experimentId);
        }
        if (blockNo < 1 || blockNo > experiment.blockCount()) {
            throw ApiException.notFound("区组不存在: " + blockNo);
        }
        return experiment;
    }

    private ReplacementView toView(ReplacementRow row) {
        return new ReplacementView(row.replaceKey(), row.experimentId(), row.blockNo(),
                row.allocationId(), row.originalParticipantId(), row.newParticipantId(),
                row.actorId(), row.replacedAt());
    }
}

-- 实验盲法分配表结构；运行于 H2 MySQL 兼容模式，数据仅在 JVM 生命周期内保留。

CREATE TABLE IF NOT EXISTS experiment (
    id          VARCHAR(64)  NOT NULL,
    block_count INT          NOT NULL,
    status      VARCHAR(16)  NOT NULL,
    created_at  BIGINT       NOT NULL,
    CONSTRAINT pk_experiment PRIMARY KEY (id),
    CONSTRAINT ck_experiment_block_count CHECK (block_count BETWEEN 2 AND 8),
    CONSTRAINT ck_experiment_status CHECK (status IN ('OPEN', 'CLOSED'))
);
COMMENT ON TABLE  experiment IS '实验表，experimentId 全局唯一，创建后区组数量与席位内容不可修改';
COMMENT ON COLUMN experiment.id IS '实验编号，业务唯一，创建时由请求给定';
COMMENT ON COLUMN experiment.block_count IS '区组数量，取值2~8，创建时固定，每组固定4个席位';
COMMENT ON COLUMN experiment.status IS '实验状态：OPEN=开放登记；CLOSED=已关闭，关闭后拒绝新增分配';
COMMENT ON COLUMN experiment.created_at IS '创建时间，Unix 毫秒，UTC';

CREATE TABLE IF NOT EXISTS seat (
    experiment_id VARCHAR(64) NOT NULL,
    block_no      INT         NOT NULL,
    seat_no       INT         NOT NULL,
    treatment     VARCHAR(1)  NOT NULL,
    CONSTRAINT pk_seat PRIMARY KEY (experiment_id, block_no, seat_no),
    CONSTRAINT ck_seat_block_no CHECK (block_no >= 1),
    CONSTRAINT ck_seat_seat_no CHECK (seat_no BETWEEN 1 AND 4),
    CONSTRAINT ck_seat_treatment CHECK (treatment IN ('A', 'B'))
);
COMMENT ON TABLE  seat IS '席位表（处理映射）：每区组4席，按提交顺序固定两个A两个B，之后不可改；仅保存于数据库';
COMMENT ON COLUMN seat.experiment_id IS '所属实验编号';
COMMENT ON COLUMN seat.block_no IS '区组号，从1开始，按区组顺序分配';
COMMENT ON COLUMN seat.seat_no IS '区组内席位号1~4，属于可直接解码信息，禁止通过普通接口暴露';
COMMENT ON COLUMN seat.treatment IS '处理代码 A 或 B，盲底，仅揭盲批准后可返回给申请人';

CREATE TABLE IF NOT EXISTS allocation (
    id             BIGINT       NOT NULL AUTO_INCREMENT,
    experiment_id  VARCHAR(64)  NOT NULL,
    participant_id VARCHAR(64)  NOT NULL,
    block_no       INT          NOT NULL,
    seat_no        INT          NOT NULL,
    blind_code     VARCHAR(32)  NOT NULL,
    status         VARCHAR(16)  NOT NULL,
    assigned_actor VARCHAR(64)  NOT NULL,
    assigned_at    BIGINT       NOT NULL,
    withdrawn_at   BIGINT,
    CONSTRAINT pk_allocation PRIMARY KEY (id),
    CONSTRAINT uq_allocation_participant UNIQUE (experiment_id, participant_id),
    CONSTRAINT uq_allocation_seat UNIQUE (experiment_id, block_no, seat_no),
    CONSTRAINT uq_allocation_blind_code UNIQUE (blind_code),
    CONSTRAINT ck_allocation_status CHECK (status IN ('ASSIGNED', 'WITHDRAWN'))
);
COMMENT ON TABLE  allocation IS '参与者分配表；同实验同参与者只占一席，退组不释放席位、不重排已有分配';
COMMENT ON COLUMN allocation.id IS '分配自增主键';
COMMENT ON COLUMN allocation.experiment_id IS '所属实验编号';
COMMENT ON COLUMN allocation.participant_id IS '合成参与者编号，非真实医疗数据';
COMMENT ON COLUMN allocation.block_no IS '分配到的区组号，普通查询可返回';
COMMENT ON COLUMN allocation.seat_no IS '分配到的席位号，可直接解码处理代码，禁止通过普通接口暴露';
COMMENT ON COLUMN allocation.blind_code IS '随机生成的无含义盲码，全局唯一，与区组/席位无对应规律';
COMMENT ON COLUMN allocation.status IS '分配状态：ASSIGNED=在组；WITHDRAWN=已退组（席位仍保留）；参与者被替补后其分配行原地转移给替补者，原参与者的 REPLACED 终态由 replacement 表派生，不落本表';
COMMENT ON COLUMN allocation.assigned_actor IS '执行登记（或替补登记）的操作者编号（X-Actor-Id）';
COMMENT ON COLUMN allocation.assigned_at IS '分配时间，Unix 毫秒，UTC；替补后重置为替补时刻';
COMMENT ON COLUMN allocation.withdrawn_at IS '退组时间，Unix 毫秒，UTC；NULL 表示未退组';

CREATE TABLE IF NOT EXISTS replacement (
    id                      BIGINT       NOT NULL AUTO_INCREMENT,
    replace_key             VARCHAR(64)  NOT NULL,
    experiment_id           VARCHAR(64)  NOT NULL,
    block_no                INT          NOT NULL,
    allocation_id           BIGINT       NOT NULL,
    original_participant_id VARCHAR(64)  NOT NULL,
    new_participant_id      VARCHAR(64)  NOT NULL,
    actor_id                VARCHAR(64)  NOT NULL,
    replaced_at             BIGINT       NOT NULL,
    CONSTRAINT pk_replacement PRIMARY KEY (id),
    CONSTRAINT uq_replacement_key UNIQUE (replace_key),
    CONSTRAINT uq_replacement_original UNIQUE (experiment_id, original_participant_id),
    CONSTRAINT uq_replacement_new UNIQUE (experiment_id, new_participant_id)
);
COMMENT ON TABLE  replacement IS '受试者替补记录表；记录不可变，不保存处理代码与席位号等盲底；替补不新建分配序号，原分配行原地转移给替补参与者';
COMMENT ON COLUMN replacement.id IS '替补记录自增主键';
COMMENT ON COLUMN replacement.replace_key IS '操作人提交的替补业务键，全局唯一，重复使用返回409';
COMMENT ON COLUMN replacement.experiment_id IS '所属实验编号';
COMMENT ON COLUMN replacement.block_no IS '原参与者所属区组号，替补参与者继承';
COMMENT ON COLUMN replacement.allocation_id IS '被继承的分配序号（allocation.id），替补前后不变';
COMMENT ON COLUMN replacement.original_participant_id IS '原合成参与者编号，替补后处于 REPLACED 终态；同实验内至多被替补一次';
COMMENT ON COLUMN replacement.new_participant_id IS '替补合成参与者编号，继承原参与者的区组与处理代码；同实验内至多参与一次替补';
COMMENT ON COLUMN replacement.actor_id IS '执行替补的操作者编号（X-Actor-Id）';
COMMENT ON COLUMN replacement.replaced_at IS '替补时间，Unix 毫秒，UTC';

CREATE TABLE IF NOT EXISTS unblind_request (
    id                      VARCHAR(64)  NOT NULL,
    experiment_id           VARCHAR(64)  NOT NULL,
    participant_id          VARCHAR(64)  NOT NULL,
    allocation_id           BIGINT       NOT NULL,
    reason                  VARCHAR(500) NOT NULL,
    applicant_actor         VARCHAR(64)  NOT NULL,
    reviewer_actor          VARCHAR(64),
    status                  VARCHAR(16)  NOT NULL,
    treatment               VARCHAR(1),
    created_at              BIGINT       NOT NULL,
    reviewed_at             BIGINT,
    pending_allocation_id   BIGINT,
    CONSTRAINT pk_unblind_request PRIMARY KEY (id),
    CONSTRAINT uq_unblind_pending UNIQUE (pending_allocation_id),
    CONSTRAINT ck_unblind_status CHECK (status IN ('PENDING', 'APPROVED')),
    CONSTRAINT ck_unblind_treatment CHECK (treatment IS NULL OR treatment IN ('A', 'B'))
);
COMMENT ON TABLE  unblind_request IS '揭盲申请表；同一分配至多一个待审申请，须由另一名 REVIEWER 批准后申请人方可查看结果';
COMMENT ON COLUMN unblind_request.id IS '揭盲申请编号，全局唯一';
COMMENT ON COLUMN unblind_request.experiment_id IS '所属实验编号';
COMMENT ON COLUMN unblind_request.participant_id IS '被申请揭盲的合成参与者编号';
COMMENT ON COLUMN unblind_request.allocation_id IS '对应分配主键';
COMMENT ON COLUMN unblind_request.reason IS '揭盲原因，必填，非空';
COMMENT ON COLUMN unblind_request.applicant_actor IS '申请人操作者编号，须为 COORDINATOR，且只有其本人能查询揭盲结果';
COMMENT ON COLUMN unblind_request.reviewer_actor IS '批准的 REVIEWER 操作者编号，必须不同于申请人；未批准时为 NULL';
COMMENT ON COLUMN unblind_request.status IS '申请状态：PENDING=待审；APPROVED=已批准';
COMMENT ON COLUMN unblind_request.treatment IS '揭盲结果处理代码 A/B，批准时写入；NULL=尚未批准';
COMMENT ON COLUMN unblind_request.created_at IS '申请时间，Unix 毫秒，UTC';
COMMENT ON COLUMN unblind_request.reviewed_at IS '批准时间，Unix 毫秒，UTC；NULL 表示未批准';
COMMENT ON COLUMN unblind_request.pending_allocation_id IS '待审去重列：待审时等于 allocation_id，终态置 NULL；唯一索引保证同一分配至多一个待审申请';

CREATE TABLE IF NOT EXISTS idempotent_request (
    request_id      VARCHAR(64)  NOT NULL,
    actor_id        VARCHAR(64)  NOT NULL,
    role            VARCHAR(16)  NOT NULL,
    operation       VARCHAR(64)  NOT NULL,
    fingerprint     VARCHAR(128) NOT NULL,
    response_status INT          NOT NULL,
    response_body   CLOB,
    created_at      BIGINT       NOT NULL,
    CONSTRAINT pk_idempotent_request PRIMARY KEY (request_id)
);
COMMENT ON TABLE  idempotent_request IS '写操作幂等记录表；仅记录成功请求，失败不占键，与业务变更同一事务原子提交';
COMMENT ON COLUMN idempotent_request.request_id IS '全局唯一 requestId（X-Request-Id）';
COMMENT ON COLUMN idempotent_request.actor_id IS '首次成功调用的操作者编号，属于幂等参数的一部分';
COMMENT ON COLUMN idempotent_request.role IS '首次成功调用的角色 COORDINATOR/REVIEWER，属于幂等参数的一部分';
COMMENT ON COLUMN idempotent_request.operation IS '写操作标识，如 experiment.create/allocation.create';
COMMENT ON COLUMN idempotent_request.fingerprint IS '请求参数指纹（含路径参数与请求体），与 actor/role 共同判定同参/异参';
COMMENT ON COLUMN idempotent_request.response_status IS '首次成功响应的 HTTP 状态码，重放时原样返回';
COMMENT ON COLUMN idempotent_request.response_body IS '首次成功响应体 JSON，重放时原样返回';
COMMENT ON COLUMN idempotent_request.created_at IS '记录时间，Unix 毫秒，UTC';
